ST.xhtml:
// 1. Generate a 1-Second Heartbeat Pulse
fbTimer(IN := NOT fbTimer.Q, PT := T#1S);

IF fbTimer.Q THEN
    udiTotalSeconds := udiTotalSeconds + 1;
END_IF

// 2. Generate a 60-Second Pulse for Persistent Logging
fbLogTimer(IN := NOT fbLogTimer.Q, PT := T#60S);

IF fbLogTimer.Q THEN
    udiTotalMinutes := udiTotalMinutes + 1;
    udiSaveCount    := udiSaveCount + 1; // Tracks every successful minute saved
END_IF

// 3. Optional Debug Reset Flag
IF bResetUptime THEN
    udiTotalSeconds := 0;
    udiTotalMinutes := 0;
    udiSaveCount    := 0;
    bResetUptime    := FALSE;
END_IF


// Master Start Command across completely different device types
IF bStartAll THEN
    FOR i := 1 TO 4 DO
        aActuators[i].Start();
    END_FOR
    bStartAll := FALSE;
END_IF

// Master Stop Command
IF bStopAll THEN
    FOR i := 1 TO 4 DO
        aActuators[i].Stop();
    END_FOR
    bStopAll := FALSE;
END_IF

// Master Reset Command
IF bResetAll THEN
    FOR i := 1 TO 4 DO
        aActuators[i].ResetFault();
    END_FOR
    bResetAll := FALSE;
END_IF

// Cyclic execution for all registered actuators
FOR i := 1 TO 4 DO
    aActuators[i].CyclicUpdate();
END_FOR

// --- Phase 3: Synchronize OOP Actuators to Fieldbus Process Data ---
bECAT_MotorEnableOut   := fbConveyorMotor.IsRunning;
iECAT_MotorVelocityOut := REAL_TO_INT(fbConveyorMotor.ActualSpeed);
bPNIO_ValveOpenOut     := fbMainValve.IsRunning;

// --- Fieldbus Health & Safety Interlock ---
bFieldbusFault := bSimulateBusDrop;

IF bFieldbusFault THEN
    FOR i := 1 TO 4 DO
        aActuators[i].Stop();
    END_FOR
END_IF

IF NOT _bFault THEN
    _bRunning := TRUE;
    Start := TRUE;
ELSE
    Start := FALSE;
END_IF

// Execute the parent timer logic first
SUPER^.CyclicUpdate();

// Add motor-specific speed ramping
IF _bRunning AND (_rActualSpeed < _rTargetSpeed) THEN
    _rActualSpeed := _rActualSpeed + 25.0;
ELSIF NOT _bRunning AND (_rActualSpeed > 0.0) THEN
    _rActualSpeed := _rActualSpeed - 50.0;
END_IF

SUPER^.CyclicUpdate();

// Add motor-specific speed ramping
IF _bRunning AND (_rActualTemp < _rTargetTemp) THEN
    _rActualTemp := _rActualTemp + 0.5;
ELSIF NOT _bRunning AND (_rActualTemp > 20) THEN
    _rActualTemp := _rActualTemp - 0.2;
	IF _rActualTemp < 20 THEN
		_rActualTemp := 20;
	END_IF
END_IF
